import{_ as o,a as t,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第三册：培养技能 · 全册语法总结 · 目的不定式与 for doing至because、therefore 与因果关系","description":"按课时归集语法规则、原创例句和易错边界。","frontmatter":{"title":"第三册：培养技能 · 全册语法总结 · 目的不定式与 for doing至because、therefore 与因果关系","description":"按课时归集语法规则、原创例句和易错边界。","splitFrom":"life/english/new-concept/book-3/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 全册语法总结","summary":"按课时归集语法规则、原创例句和易错边界。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 全册语法总结 · 条件句中的礼貌距离至by、until 与时刻表现在时","link":"/life/english/new-concept/book-3/grammar-part-04"},"next":{"text":"第三册：培养技能 · 全册语法总结 · 地点前置的完全倒装至as if 与假设语气","link":"/life/english/new-concept/book-3/grammar-part-06"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 全册语法总结 · 条件句中的礼貌距离至by、until 与时刻表现在时","link":"/life/english/new-concept/book-3/grammar-part-04"},"next":{"text":"第三册：培养技能 · 全册语法总结 · 地点前置的完全倒装至as if 与假设语气","link":"/life/english/new-concept/book-3/grammar-part-06"}},"headers":[],"relativePath":"life/english/new-concept/book-3/grammar-part-05.md","filePath":"life/english/new-concept/book-3/grammar-part-05.md"}'),r={name:"life/english/new-concept/book-3/grammar-part-05.md"};function s(i,e,l,h,p,c){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-全册语法总结-·-目的不定式与-for-doing至because、therefore-与因果关系" tabindex="-1">第三册：培养技能 · 全册语法总结 · 目的不定式与 for doing至because、therefore 与因果关系 <a class="header-anchor" href="#第三册-培养技能-·-全册语法总结-·-目的不定式与-for-doing至because、therefore-与因果关系" aria-label="Permalink to &quot;第三册：培养技能 · 全册语法总结 · 目的不定式与 for doing至because、therefore 与因果关系&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/overview">本册介绍</a> · <a href="/life/english/new-concept/book-3/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-3/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-3/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-3/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-3/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-3/review">综合复习与自测</a></p><h2 id="目的不定式与-for-doing" tabindex="-1">目的不定式与 for doing <a class="header-anchor" href="#目的不定式与-for-doing" aria-label="Permalink to &quot;目的不定式与 for doing {#目的不定式与-for-doing}&quot;">​</a></h2><p>to do 常说明行为目的，即某人为了什么采取行动；for doing 常说明物品用途或某种功能。A tool for measuring 是测量工具，He used a tool to measure 说明他使用工具的目的。in order to 更明确地标出目的，否定写 in order not to。不是所有 for 加 ing 都表示目的，也可能表示原因或感谢对象，应根据动词搭配判断。讨论古物用途时，may have been used to ... 保留推断空间，不能将可能用途写成确定事实。</p><p><strong>L38 原创例句：</strong> The group marked a stone each evening to keep track of passing days.</p><p>这群人每天晚上在石头上做记号，以记录日子的推移。</p><p><strong>易错：</strong> a tool for measure 应为 a tool for measuring；目的不定式则是 used it to measure。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-038">Lesson 38</a></p><h2 id="不定式后置修饰与介词" tabindex="-1">不定式后置修饰与介词 <a class="header-anchor" href="#不定式后置修饰与介词" aria-label="Permalink to &quot;不定式后置修饰与介词 {#不定式后置修饰与介词}&quot;">​</a></h2><p>名词或不定代词后可接不定式说明待完成的动作，例如 a route to follow。若被修饰词在不定式中相当于介词宾语，通常须保留介词，如 a person to talk to、nothing to worry about。若动词本身可直接带宾语，则不另加介词，如 a book to read。某些地点词如 place 后的介词可因惯用结构省略，但不应据此随意删除所有介词。此类短语常带潜在动作或用途，不能简单当作已发生的过去事实。</p><p><strong>L39 原创例句：</strong> We had a reliable guide to consult and a marked path to follow.</p><p>我们有可靠向导可以咨询，也有标记清楚的小路可走。</p><p><strong>易错：</strong> I need someone to speak 应表达为 someone to speak to，若意思是“需要一个说话者”，则原结构可能有不同含义。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-039">Lesson 39</a></p><h2 id="反身代词与相互代词" tabindex="-1">反身代词与相互代词 <a class="header-anchor" href="#反身代词与相互代词" aria-label="Permalink to &quot;反身代词与相互代词 {#反身代词与相互代词}&quot;">​</a></h2><p>myself、yourself、himself 等反身代词可在主语与宾语指同一对象时使用，也可放在名词或句末强调本人。by oneself 常表示独自或不借助他人。each other 表示不同成员之间的相互动作，与 themselves 意义不同。They introduced themselves 是各自介绍自己，They introduced each other 是互相介绍对方。反身代词不能只为显得正式而代替普通宾格，例如 Please contact me 通常比 contact myself 更合适，除非有明确反身或强调语境。</p><p><strong>L40 原创例句：</strong> The two actors introduced themselves before they introduced each other to the director.</p><p>两位演员先介绍自己，然后向导演介绍了对方。</p><p><strong>易错：</strong> They looked at themselves 表示看自己，looked at each other 表示彼此对视，不能互换。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-040">Lesson 40</a></p><h2 id="while-与-whereas-的对照" tabindex="-1">while 与 whereas 的对照 <a class="header-anchor" href="#while-与-whereas-的对照" aria-label="Permalink to &quot;while 与 whereas 的对照 {#while-与-whereas-的对照}&quot;">​</a></h2><p>while 可表示“当……时”的同时背景，也可表示两种事实的对比，具体意义取决于分句是否构成并列差异。whereas 明确表示对照，通常不表示时间。两者都可连接完整分句，主语不必相同。对照不自动等于逻辑矛盾，例如一个地方清静而交通不便是两个维度，而不是互相否定。写比较段落时尽量让两侧使用相同评价标准和相近结构，读者才能看出差别；若需要表达承认条件但仍得出结论，应考虑 although 的让步关系。</p><p><strong>L41 原创例句：</strong> The village is quiet after sunset, whereas the market town remains busy until midnight.</p><p>村庄日落后很安静，而集镇一直忙碌到午夜。</p><p><strong>易错：</strong> while 不能每次都译作“当……时”；While Anna likes silence, Ben enjoys company 中表达的是偏好对照。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-041">Lesson 41</a></p><h2 id="独立主格的独立主语" tabindex="-1">独立主格的独立主语 <a class="header-anchor" href="#独立主格的独立主语" aria-label="Permalink to &quot;独立主格的独立主语 {#独立主格的独立主语}&quot;">​</a></h2><p>名词或代词加分词等成分可构成独立主格，为主句补充时间、原因或伴随情况，其逻辑主语不同于主句主语。The entrance blocked, we chose another route 中 blocked 与 entrance 构成被动关系。主动进行可用 ing，完成或被动可用过去分词，某些结构也可用形容词或介词短语。它不是完整的限定分句，不能仅用逗号连接两个都有完整谓语的独立句。该形式较书面；信息复杂时改为 because 或 when 从句通常更易理解。</p><p><strong>L42 原创例句：</strong> The main passage blocked, the team returned to the entrance.</p><p>主通道被堵住了，团队便返回入口。</p><p><strong>易错：</strong> The passage was blocked, the team returned 属于逗号拼接两个完整句，需加 so、用分号或改为从句。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-042">Lesson 42</a></p><h2 id="provided-that-与-unless" tabindex="-1">provided that 与 unless <a class="header-anchor" href="#provided-that-与-unless" aria-label="Permalink to &quot;provided that 与 unless {#provided-that-与-unless}&quot;">​</a></h2><p>provided that 或 providing that 表示“只要满足条件”，后接完整分句；unless 通常表示“除非”，相当于 if ... not，但遇到复杂否定、反事实或表达例外时不能机械替换。条件从句谈将来时常用一般现在时，主句才使用 will。unless 本身已含否定条件，通常不再加入 not，除非确实要表达另一层否定。解读条款语言时，必须同时识别条件、结果和例外，语法练习中的虚构规则不能推定为任何现实服务的承诺。</p><p><strong>L43 原创例句：</strong> In this fictional scheme, repairs are covered provided that the damage is reported within a week.</p><p>在这个虚构方案中，只要一周内报告损坏，维修费用就在保障范围内。</p><p><strong>易错：</strong> Unless you don&#39;t report it 会形成额外否定，若意为“如果不报告”，直接写 unless you report it。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-043">Lesson 43</a></p><h2 id="平行结构与-not-only" tabindex="-1">平行结构与 not only <a class="header-anchor" href="#平行结构与-not-only" aria-label="Permalink to &quot;平行结构与 not only {#平行结构与-not-only}&quot;">​</a></h2><p>and、or、both ... and、not only ... but also 连接的成分应尽量保持相同语法层次，如两个名词、两个形容词或两个分句。not only 置于句首并强调整个分句时，前半句通常部分倒装，后半句保持常规语序；若它只位于句中修饰两个宾语，则不需要倒装。平行结构提高可读性，但不能代替论证。比较交通时，还应把门到门时间和车上时间区分开，否则句式工整也可能得出误导性结论。</p><p><strong>L44 原创例句：</strong> The night train offers both a quiet place to sleep and a direct route to the city centre.</p><p>夜间列车既提供安静睡眠的地方，又提供直达市中心的路线。</p><p><strong>易错：</strong> both comfortable and saves time 不平行；可改为 both comfortable and convenient，或 It is comfortable and saves time。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-044">Lesson 44</a></p><h2 id="报告动词及其结构" tabindex="-1">报告动词及其结构 <a class="header-anchor" href="#报告动词及其结构" aria-label="Permalink to &quot;报告动词及其结构 {#报告动词及其结构}&quot;">​</a></h2><p>say 常接内容从句，tell 通常先接人再接内容，claim 表示声称而不必担保真实性，confirm 表示确认某信息。suggest 可接 doing，也可接 that 从句；表示建议时，正式英语可用 should do 或原形虚拟式，不能写 suggest someone to do。不同动词不只是替换 said 的修辞工具，它们会改变信息来源与可信度的呈现。报道时须匹配原说话人的言语行为，避免把推测写成确认，或把建议写成命令。</p><p><strong>L45 原创例句：</strong> The reporter stated the figures, while the campaigner claimed that they showed a wider problem.</p><p>记者陈述了数字，而倡议者声称这些数字反映了更广泛的问题。</p><p><strong>易错：</strong> She suggested me to write 错误；可写 She suggested that I write 或 She suggested writing，视执行者是否需要明确。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-045">Lesson 45</a></p><h2 id="过去能力与一次成功" tabindex="-1">过去能力与一次成功 <a class="header-anchor" href="#过去能力与一次成功" aria-label="Permalink to &quot;过去能力与一次成功 {#过去能力与一次成功}&quot;">​</a></h2><p>could 常表示过去的一般能力，也可用于感知、理解或特定条件下的可能性。描述过去某一次实际克服困难并成功完成，was able to 或 managed to 往往更明确；managed to 还暗含有难度。否定 couldn&#39;t 可以表示一次未能完成，因此不是简单地把 could 禁用于所有单次事件。能力、许可和可能性也可能共用 could，必须结合语境判断。维修叙述中应分别报告尝试与结果，tried to 不保证成功，managed to 则通常表示已实现。</p><p><strong>L46 原创例句：</strong> After several careful attempts, I managed to remove the damaged screw.</p><p>经过几次小心尝试，我终于取出了损坏的螺丝。</p><p><strong>易错：</strong> I tried to fix it 不表示已经修好；若要确认成功，可写 I managed to fix it。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-046">Lesson 46</a></p><h2 id="because、therefore-与因果关系" tabindex="-1">because、therefore 与因果关系 <a class="header-anchor" href="#because、therefore-与因果关系" aria-label="Permalink to &quot;because、therefore 与因果关系 {#because、therefore-与因果关系}&quot;">​</a></h2><p>because 引导原因从句，能与主句构成一个复合句；therefore 是连接性副词，通常需要句号、分号或与连词配合来连接独立分句，不能仅用一个逗号代替句法连接。because of 后接名词性成分，不能直接接完整分句。语法上的因果标记也需要证据支持，两个现象先后发生不自动构成因果。讨论公共问题时可使用 may contribute to 限定影响，避免把复杂结果归因于单一因素或把个人感受说成普遍事实。</p><p><strong>L47 原创例句：</strong> The courtyard remained noisy after midnight; therefore, several residents moved their bedrooms to the rear.</p><p>午夜后庭院仍很嘈杂，因此几位住户把卧室改设在后侧。</p><p><strong>易错：</strong> Because of the traffic was loud 错把完整句接在介词后；可写 Because the traffic was loud 或 Because of the loud traffic。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-047">Lesson 47</a></p>',63)])])}const f=o(r,[["render",s]]);export{g as __pageData,f as default};
